#include <bits/stdc++.h>
using namespace std;

struct Point {
    double x, y;
    Point(double x_=0, double y_=0): x(x_), y(y_) {}
    Point sub(const Point& o) const { return Point(x - o.x, y - o.y); }
    Point moveAlongLine(const struct Line& l, double len) const;
    Point moveAlongVector(const Point& v, double len) const;
    Point add(const Point& o) const { return Point(x + o.x, y + o.y); }
    Point mul(double f) const { return Point(x * f, y * f); }
    Point getAlpha() const { return Point(-y, x); }
    bool equals(const Point& o) const {
        return std::abs(x - o.x) < 1e-10 && std::abs(y - o.y) < 1e-10;
    }
    int compareTo(const Point& o) const {
        if (equals(o)) return 0;
        if (std::abs(x - o.x) < 1e-10) return (y < o.y) ? -1 : 1;
        return (x < o.x) ? -1 : 1;
    }
};

struct Line {
    Point from, to;
    Line(const Point& f, const Point& t): from(f), to(t) {}
    Point asVector() const { return to.sub(from); }
    double length() const { return hypot(to.x - from.x, to.y - from.y); }
};

Point Point::moveAlongLine(const Line& l, double len) const {
    return moveAlongVector(l.asVector(), len);
}

Point Point::moveAlongVector(const Point& v, double len) const {
    double mag = hypot(v.x, v.y);
    if (mag < 1e-15) return Point(x, y);
    return add(Point(v.x / mag, v.y / mag).mul(len));
}

struct Circle {
    Point center;
    int radius;
    Circle(int x, int y, int r): center(x, y), radius(r) {}
    static bool isIntersect(const Circle& a, const Circle& b) {
        double d = distance(a.center, b.center);
        return d <= a.radius + b.radius + 1e-10 && d + 1e-10 >= std::abs(a.radius - b.radius);
    }
    static bool isIntersect2(const Circle& a, const Circle& b) {
        double d = distance(a.center, b.center);
        return d < a.radius + b.radius && d > std::abs(a.radius - b.radius);
    }
    static void intersectAt(const Circle& a, const Circle& b, std::set<Point>& set) {
        if (!isIntersect(a, b)) return;
        Line line(a.center, b.center);
        double d = distance(a.center, b.center);
        double midDist = (d * d - b.radius * b.radius + a.radius * a.radius) / (2 * d);
        Point mid = a.center.moveAlongLine(line, midDist);
        Point alpha = line.asVector().getAlpha();
        double height = std::sqrt(a.radius * a.radius - midDist * midDist);
        Point p1 = mid.moveAlongVector(alpha, height);
        Point p2 = mid.moveAlongVector(alpha, -height);
        set.insert(p1);
        if (!p2.equals(p1)) set.insert(p2);
    }
};

double distance(const Point& a, const Point& b) {
    return hypot(a.x - b.x, a.y - b.y);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n; cin >> n;
    std::vector<Circle> circleList;
    for (int i = 0; i < n; i++) {
        int x, y, r;
        cin >> x >> y >> r;
        circleList.emplace_back(x, y, r);
    }
    if (n == 3 && !Circle::isIntersect(circleList[0], circleList[1])) {
        int sum = 4;
        if (Circle::isIntersect2(circleList[0], circleList[2])) sum++;
        if (Circle::isIntersect2(circleList[1], circleList[2])) sum++;
        cout << sum << "\n";
        return 0;
    }
    int totalCount = 1;
    std::set<Point> pointSet;
    for (int i = 0; i < n; i++) {
        pointSet.clear();
        totalCount++;
        for (int j = 0; j < i; j++) {
            Circle::intersectAt(circleList[i], circleList[j], pointSet);
        }
        if ((int)pointSet.size() >= 2) {
            totalCount += (int)pointSet.size() - 1;
        }
    }
    cout << totalCount << "\n";
    return 0;
}

